import{_ as r,o as a,c as n,ag as t}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年8月25日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-25.md","filePath":"science-log/src/reconstructed/2026-08-25.md"}'),o={name:"science-log/src/reconstructed/2026-08-25.md"};function i(s,e,l,h,g,c){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="🔬-科学快报-2026年8月25日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月25日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月25日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月25日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202608250000 TO 202608252359]</code>（cs.AI，命中 30 篇）｜ 重建日：2026-11-05 当日 Nature（0028-0836）CrossRef 在线命中 17 条，全部为新闻/Briefing 与 1 条勘误（Addendum），<strong>无研究论文</strong>；Science 系（10.1126）该日以新闻稿为主。科学 5 篇全部取自 PNAS（0027-8424）当日在线发布（CrossRef <code>from-online-pub-date</code> 命中 24 条）的真实研究论文。</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-哺乳动物中广泛存在钠、锂结合-rna-适配体" tabindex="-1">🧬 哺乳动物中广泛存在钠、锂结合 RNA 适配体 <a class="header-anchor" href="#🧬-哺乳动物中广泛存在钠、锂结合-rna-适配体" aria-label="Permalink to &quot;🧬 哺乳动物中广泛存在钠、锂结合 RNA 适配体&quot;">​</a></h3><p><strong>RNA aptamers for sodium and lithium are abundant in mammals</strong><em>PNAS (2026)</em></p><p>耶鲁大学分子、细胞与发育生物学系 Ronald R. Breaker 团队的 Neil White 等人，用比较序列分析在人类及其他哺乳动物中找出大量与细菌核糖开关（riboswitch）钠/锂适配体序列、结构相似的 RNA 基序。候选基序出现在约 70 个与离子传导、神经元发育与功能或多种神经疾病相关的基因 mRNA 转录本里。生物信息学与生化实验共同支持「哺乳动物大量使用这类 RNA 适配体选择性结合 Na⁺ 与 Li⁺」的假说，且这些结构化 RNA 域常位于 mRNA 或其反义转录本的特定区域，提示它们可能是核糖开关的组成部分。若成立，这意味着真核生物也像细菌一样用 RNA 直接感知金属离子与药物（如锂盐）并调控基因表达。📎 DOI: <a href="https://doi.org/10.1073/pnas.2618832123" target="_blank" rel="noreferrer">10.1073/pnas.2618832123</a></p><h3 id="🪐-水星地壳磁化指向更强的古代发电机" tabindex="-1">🪐 水星地壳磁化指向更强的古代发电机 <a class="header-anchor" href="#🪐-水星地壳磁化指向更强的古代发电机" aria-label="Permalink to &quot;🪐 水星地壳磁化指向更强的古代发电机&quot;">​</a></h3><p><strong>Mercury&#39;s crustal magnetization indicates a stronger ancient dynamo</strong><em>PNAS (2026)</em></p><p>麻省理工学院 I. S. Narrett、Benjamin P. Weiss 等人对古代太阳风与水星磁场相互作用做了三维磁流体力学模拟，并耦合地壳热演化与磁化模型。水星是除地球外唯一仍有活跃发电机磁场的类地行星（赤道表面约 200 nT），其约 39 亿~37 亿年前的地壳又被强烈磁化（30 km 高度约 10 nT），说明曾有更古老的发电机。模拟表明这些地壳磁化很可能由一个赤道表面强度<strong>至少约 2,000 nT</strong> 的偶极场产生——比今日水星磁场强约一个数量级，从而约束古发电机的强度与机制。📎 DOI: <a href="https://doi.org/10.1073/pnas.2608701123" target="_blank" rel="noreferrer">10.1073/pnas.2608701123</a></p><h3 id="🦗-重构侏罗纪声景-化石翅揭示超声通讯" tabindex="-1">🦗 重构侏罗纪声景：化石翅揭示超声通讯 <a class="header-anchor" href="#🦗-重构侏罗纪声景-化石翅揭示超声通讯" aria-label="Permalink to &quot;🦗 重构侏罗纪声景：化石翅揭示超声通讯&quot;">​</a></h3><p><strong>Reconstruction of an extinct soundscape reveals ultrasonic communication in the Jurassic</strong><em>PNAS (2026)</em></p><p>恐龙等脊椎动物的发声器官极少保存，但部分节肢动物硬化角质层里的发声结构（音锉、刮器）可以随化石保存。Gu JJ、任东等人测量雄性蟋蟀及其近亲化石前翅上的摩擦发声结构——这些化石自带其所产生声信号的「指纹」，再结合系统发育信息推断叫声频率，进而重建出侏罗纪森林的古声景。结果显示当时已存在<strong>超声频段</strong>的通讯，把昆虫超声通讯的历史大幅前推。这为「用化石形态反演已灭绝声环境」提供了一条可复制的路径。📎 DOI: <a href="https://doi.org/10.1073/pnas.2615107123" target="_blank" rel="noreferrer">10.1073/pnas.2615107123</a></p><h3 id="⚛️-光学与回旋有效质量之差-统一-cecoin5-的奇异金属输运" tabindex="-1">⚛️ 光学与回旋有效质量之差，统一 CeCoIn₅ 的奇异金属输运 <a class="header-anchor" href="#⚛️-光学与回旋有效质量之差-统一-cecoin5-的奇异金属输运" aria-label="Permalink to &quot;⚛️ 光学与回旋有效质量之差，统一 CeCoIn₅ 的奇异金属输运&quot;">​</a></h3><p><strong>Reconciling strange metal transport in CeCoIn₅ through the difference of optical and cyclotron effective masses</strong><em>PNAS (2026)</em></p><p>铜氧化物超导体的「奇异金属」行为——电阻率随温度线性、霍尔输运反常——与常规费米液体理论相悖；重费米子金属 CeCoIn₅ 也有类似输运与 d 波超导、强反铁磁涨落。Johns Hopkins 的 N. P. Armitage 团队用<strong>时域太赫兹光谱</strong>在宽磁场范围测量 CeCoIn₅ 奇异金属态的光学电导，发现电流弛豫率大致随 T² 变化（费米液体的特征），并通过光学有效质量与回旋有效质量之差来调和奇异金属输运的表观矛盾。这把太赫兹光学测量定位为分辨「真奇异金属」与「多带/质量重整化效应」的关键工具。📎 DOI: <a href="https://doi.org/10.1073/pnas.2614197123" target="_blank" rel="noreferrer">10.1073/pnas.2614197123</a></p><h3 id="🔬-离子强度如何调控-kinesin-14-运动性" tabindex="-1">🔬 离子强度如何调控 kinesin-14 运动性 <a class="header-anchor" href="#🔬-离子强度如何调控-kinesin-14-运动性" aria-label="Permalink to &quot;🔬 离子强度如何调控 kinesin-14 运动性&quot;">​</a></h3><p><strong>On the origin of the ionic strength control of the motility of kinesin-14</strong><em>PNAS (2026)</em></p><p>kinesin-14 是与常规驱动蛋白方向相反的「负端马达」，其运动性显著依赖溶液离子强度——这是细胞运输的基本问题，但分子起源长期不清。南加州大学 R. Halder 与 A. Warshel 结合<strong>受控分子动力学（steered MD）、伞形采样与结合能分析</strong>，解释了离子强度升高为何降低 kinesin-14 的运动性：离子屏蔽改变马达与微管间的静电相互作用与结合自由能，从而削弱其沿微管行走的能力。工作体现了「静电极化环境」如何直接决定分子马达的力学输出。📎 DOI: <a href="https://doi.org/10.1073/pnas.2618972123" target="_blank" rel="noreferrer">10.1073/pnas.2618972123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧪-output-dilution-moe-模型里冗余却脆弱的道德表征" tabindex="-1">🧪 Output Dilution：MoE 模型里冗余却脆弱的道德表征 <a class="header-anchor" href="#🧪-output-dilution-moe-模型里冗余却脆弱的道德表征" aria-label="Permalink to &quot;🧪 Output Dilution：MoE 模型里冗余却脆弱的道德表征&quot;">​</a></h3><p><strong>Output Dilution: Redundant but Fragile Representations in MoE Models</strong><em>arXiv (2026)</em></p><p>Orion Reblitz-Richardson 发现，混合专家（MoE）模型看似像稠密模型一样稳健地编码道德内容，实则脆弱得多。在 OLMoE-1B-7B 中，线性探针几乎能从每个「专家—层」组合中读出道德效价（峰值层平均准确率 &gt;90%），但这些表征在<strong>同规模稠密模型轻松承受的激活噪声</strong>下就崩塌，稳健性差 4.2 倍。作者把根因归结为「输出稀释」：MoE 块在汇入残差流前要先对各激活专家求平均，到达下游层的前馈信号比稠密 MLP 小近两个数量级，因此信息虽冗余却难以承受扰动。📎 arXiv: <a href="https://arxiv.org/abs/2608.25231" target="_blank" rel="noreferrer">2608.25231</a></p><h3 id="🛠️-用表征调控调节-llm-智能体的工具调用率" tabindex="-1">🛠️ 用表征调控调节 LLM 智能体的工具调用率 <a class="header-anchor" href="#🛠️-用表征调控调节-llm-智能体的工具调用率" aria-label="Permalink to &quot;🛠️ 用表征调控调节 LLM 智能体的工具调用率&quot;">​</a></h3><p><strong>Tunable Tool-Call Rates in LLM Agents via Representation Steering</strong><em>arXiv (2026)</em></p><p>「是否该调用工具」是 LLM 智能体的核心能力，且代价高昂：多余调用增加延迟与成本、甚至触发不可逆副作用，漏掉调用又让模型在只能靠工具回答的问题上「自信地错」。Yuqi Chen、Vincent Siu、Yang Liu、Dawn Song、Chenguang Wang 证明，指令微调模型是否调用工具，可由残差流中的<strong>单一线性方向</strong>控制——该方向无需任何训练，直接从模型自身的工具使用偏好信号中提取，因而可在推理时按需调节工具调用倾向，克服后训练与提示工程「昂贵且难在推理时改动」的缺陷。📎 arXiv: <a href="https://arxiv.org/abs/2608.25198" target="_blank" rel="noreferrer">2608.25198</a></p><h3 id="🗣️-信念级联驱动-llm-智能体网络中的说服" tabindex="-1">🗣️ 信念级联驱动 LLM 智能体网络中的说服 <a class="header-anchor" href="#🗣️-信念级联驱动-llm-智能体网络中的说服" aria-label="Permalink to &quot;🗣️ 信念级联驱动 LLM 智能体网络中的说服&quot;">​</a></h3><p><strong>Belief Cascades Drive Persuasion in LLM Agent Networks</strong><em>arXiv (2026)</em></p><p>多智能体 LLM 系统越来越多地用于辩论、协作研究与信息中介，智能体间的「说服」成了基础却测量不足的能力。Haoyi Qiu 等搭建了一个可控试验台：让有目标的「说服者」在基于真实自我网络（ego-network）拓扑的 LLM 智能体网络中改变同伴立场，覆盖 4 个 LLM 骨干、5 种图结构、55 条政策陈述。结果显示说服动力学依赖拓扑、竞争、话题与模型先验的交互；<strong>直接暴露能稳定预测下一轮立场改变</strong>，同伴转述的影响更小但可测量——形如「信念级联」。📎 arXiv: <a href="https://arxiv.org/abs/2608.25152" target="_blank" rel="noreferrer">2608.25152</a></p><h3 id="✅-flare-用-llm-定理证明验证-milp-重构" tabindex="-1">✅ FLARE：用 LLM 定理证明验证 MILP 重构 <a class="header-anchor" href="#✅-flare-用-llm-定理证明验证-milp-重构" aria-label="Permalink to &quot;✅ FLARE：用 LLM 定理证明验证 MILP 重构&quot;">​</a></h3><p><strong>FLARE: Verifying MILP Reformulations with LLM-Based Theorem Proving</strong><em>arXiv (2026)</em></p><p>混合整数线性规划（MILP）重构的自动化设计是 LLM 的新用武之地，但要可靠自动化，必须能验证「重构后的模型仍等价于原优化问题」。现有方法只做数值评估，无法对一般问题实例给出理由。Henry Robbins、Connor Lawless、Madeleine Udell、Ellen Vitercik 提出 MILP 重构的<strong>构造性定义</strong>，使其可被形式化表达，再用基于 LLM 的定理证明来验证重构保持原问题——把「模型改写」的正确性从抽样检查升级为可证明的保证，对自动化优化建模意义直接。📎 arXiv: <a href="https://arxiv.org/abs/2608.25220" target="_blank" rel="noreferrer">2608.25220</a></p><h3 id="⚡-注意力架构如何影响-llm-推理能耗的缩放" tabindex="-1">⚡ 注意力架构如何影响 LLM 推理能耗的缩放 <a class="header-anchor" href="#⚡-注意力架构如何影响-llm-推理能耗的缩放" aria-label="Permalink to &quot;⚡ 注意力架构如何影响 LLM 推理能耗的缩放&quot;">​</a></h3><p><strong>Understanding the Energy Scaling of Large Language Model Inference Across Context Lengths and Attention Architectures</strong><em>arXiv (2026)</em></p><p>Molka Chkir、Syed Muhammad Danish、Jos Höll、Arghavan Asad 对解码阶段的能耗做了系统实证研究，比较采用多头注意力（MHA）、分组查询注意力（GQA）与带滑动窗的 GQA（SWA）的代表性开源 LLM。他们在不同上下文长度、批大小与生成负载下，用 NVIDIA 硬件计数器<strong>直接测量 GPU 能耗</strong>，刻画注意力架构如何影响解码能耗的缩放。工作把「能耗」这一常被忽视的部署约束放进架构选型与长上下文推理的权衡之中。📎 arXiv: <a href="https://arxiv.org/abs/2608.25096" target="_blank" rel="noreferrer">2608.25096</a></p><blockquote><p>📅 日期：2026-08-25 ｜ ⚠️ 事后重建版（第 ? 期 · 事后重建版） ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',35)])])}const u=r(o,[["render",i]]);export{p as __pageData,u as default};
